<div class="public-content-main"><section class="public-content-hero"><div class="eyebrow">FAQ</div><h1><?=store_h((string)($settings['page_faq_heading']??'Useful answers, without the fine-print maze.'))?></h1><p><?=store_h((string)($settings['page_faq_intro']??'Shopping, delivery, accounts and support in plain language.'))?></p></section><section class="public-faq public-faq-list"><?php foreach($faqRows as $faq):$question=trim((string)($faq['question']??''));$answer=trim((string)($faq['answer']??''));if($question===''||$answer==='')continue;?><details><summary><?=store_h($question)?></summary><p><?=nl2br(store_h($answer),false)?></p></details><?php endforeach;?></section></div>
